702	fn open_session_log(
703	    session_id: &str,
704	) -> anyhow::Result<codeflow_core::session::SessionLog> {
705	    let db_path = paths::db_path();
706	    let data_dir = paths::data_dir();
707	    std::fs::create_dir_all(&data_dir)?;
708	    codeflow_core::session::SessionLog::open(&db_path, session_id)
709	}
