1	use anyhow::{Context, Result};
2	use ed25519_dalek::{Signer, SigningKey, Verifier, VerifyingKey};
3	use std::path::{Path, PathBuf};
4	
5	pub struct KeyPair {
6	    signing_key: SigningKey,
7	}
8	
9	impl KeyPair {
10	    pub fn generate() -> Self {
11	        let mut csprng = rand::rngs::OsRng;
12	        Self {
13	            signing_key: SigningKey::generate(&mut csprng),
14	        }
15	    }
16	
17	    pub fn from_bytes(secret: &[u8; 32]) -> Self {
18	        Self {
19	            signing_key: SigningKey::from_bytes(secret),
20	        }
21	    }
22	
23	    pub fn sign(&self, data: &[u8]) -> String {
24	        let sig = self.signing_key.sign(data);
25	        hex::encode(&sig.to_bytes())
26	    }
27	
28	    pub fn public_key_hex(&self) -> String {
29	        hex::encode(self.signing_key.verifying_key().as_bytes())
30	    }
31	
32	    pub fn secret_bytes(&self) -> &[u8; 32] {
33	        self.signing_key.as_bytes()
34	    }
35	
36	    pub fn save(&self, path: &Path) -> Result<()> {
37	        if let Some(parent) = path.parent() {
38	            std::fs::create_dir_all(parent)?;
39	        }
40	        std::fs::write(path, self.signing_key.as_bytes())
41	            .context("failed to write signing key")?;
42	        let pub_path = path.with_extension("pub");
43	        std::fs::write(&pub_path, self.signing_key.verifying_key().as_bytes())
44	            .context("failed to write public key")?;
45	
46	        #[cfg(unix)]
47	        {
48	            use std::os::unix::fs::PermissionsExt;
49	            std::fs::set_permissions(path, std::fs::Permissions::from_mode(0o600))?;
50	        }
51	
52	        Ok(())
53	    }
54	
55	    pub fn load(path: &Path) -> Result<Self> {
56	        let bytes = std::fs::read(path).context("failed to read signing key")?;
57	        let secret: [u8; 32] = bytes
58	            .try_into()
59	            .map_err(|_| anyhow::anyhow!("invalid key length"))?;
60	        Ok(Self::from_bytes(&secret))
61	    }
62	}
63	
64	pub fn verify(public_key_hex: &str, data: &[u8], signature_hex: &str) -> bool {
65	    let Ok(pk_bytes) = hex::decode(public_key_hex) else {
66	        return false;
67	    };
68	    let Ok(pk_arr): Result<[u8; 32], _> = pk_bytes.try_into() else {
69	        return false;
70	    };
71	    let Ok(verifying_key) = VerifyingKey::from_bytes(&pk_arr) else {
72	        return false;
73	    };
74	    let Ok(sig_bytes) = hex::decode(signature_hex) else {
75	        return false;
76	    };
77	    let Ok(sig_arr): Result<[u8; 64], _> = sig_bytes.try_into() else {
78	        return false;
79	    };
80	    let signature = ed25519_dalek::Signature::from_bytes(&sig_arr);
81	    verifying_key.verify(data, &signature).is_ok()
82	}
