84	pub fn keys_dir() -> PathBuf {
85	    dirs::data_dir()
86	        .or_else(|| dirs::home_dir().map(|h| h.join(".local/share")))
87	        .expect("neither data_dir nor home_dir available — cannot store signing keys")
88	        .join("codeflow")
89	        .join("keys")
90	}
91	
92	pub fn load_or_generate() -> Result<KeyPair> {
93	    let dir = keys_dir();
94	    let key_path = dir.join("signing.key");
95	
96	    match KeyPair::load(&key_path) {
97	        Ok(kp) => return Ok(kp),
98	        Err(_) => {}
99	    }
100	
101	    if let Some(parent) = key_path.parent() {
102	        std::fs::create_dir_all(parent)?;
103	    }
104	
105	    let kp = KeyPair::generate();
106	
107	    // Atomic create-or-fail to prevent TOCTOU race between concurrent hook processes
108	    match std::fs::OpenOptions::new()
109	        .write(true)
110	        .create_new(true)
111	        .open(&key_path)
112	    {
113	        Ok(mut f) => {
114	            use std::io::Write;
115	            f.write_all(kp.secret_bytes())?;
116	            drop(f);
117	
118	            let pub_path = key_path.with_extension("pub");
119	            std::fs::write(&pub_path, kp.signing_key.verifying_key().as_bytes())?;
120	
121	            #[cfg(unix)]
122	            {
123	                use std::os::unix::fs::PermissionsExt;
124	                std::fs::set_permissions(&key_path, std::fs::Permissions::from_mode(0o600))?;
125	            }
126	
127	            Ok(kp)
128	        }
129	        Err(e) if e.kind() == std::io::ErrorKind::AlreadyExists => {
130	            // Another process won the race — load their key
131	            KeyPair::load(&key_path)
132	        }
133	        Err(e) => Err(e.into()),
134	    }
135	}
