137	mod hex {
138	    pub fn encode(bytes: &[u8]) -> String {
139	        bytes.iter().map(|b| format!("{:02x}", b)).collect()
140	    }
141	
142	    pub fn decode(s: &str) -> Result<Vec<u8>, String> {
143	        if s.len() % 2 != 0 {
144	            return Err("odd length".to_string());
145	        }
146	        (0..s.len())
147	            .step_by(2)
148	            .map(|i| u8::from_str_radix(&s[i..i + 2], 16).map_err(|e| e.to_string()))
149	            .collect()
150	    }
151	}
